update public.products set description='A mixed selection of ram meat portions suitable for soups, stews, pepper soup and other dishes that use a combination of sheep-meat cuts.', handling_protocols=array['Keep raw assorted ram meat refrigerated or frozen and separate from ready-to-eat foods.','Clean hands, knives, boards and containers after handling raw meat.','If the mix contains organ meat, cook those components thoroughly to at least 71°C / 160°F.']::text[], storage_tips=array['Because the assortment composition is not yet defined, refrigerate at 4°C or below and use within 1–2 days.','For longer storage, freeze at about -18°C or below and use within about 3–4 months for best quality.']::text[] where name='Ram Assorted' and category_id=(select id from public.product_categories where name='Meat & Poultry');
update public.products set description='Ram leg is a substantial bone-in sheep-meat cut suitable for roasting, grilling, slow cooking, soups, stews and portioning into smaller pieces.', handling_protocols=array['Keep refrigerated or frozen and separate from ready-to-eat foods.','Use clean knives and boards when portioning and clean surfaces afterwards.','Cook an intact ram leg to at least 63°C / 145°F and allow a 3-minute rest.']::text[], storage_tips=array['Refrigerate at 4°C or below and use within about 3–5 days.','For longer storage, freeze at about -18°C or below and use within about 6–9 months for best quality.']::text[] where name='Ram Leg' and category_id=(select id from public.product_categories where name='Meat & Poultry');
update public.products set description='Fresh boneless ram meat with the bones removed, suitable for soups, stews, sauces, grilling and other sheep-meat dishes.', handling_protocols=array['Keep raw meat cold and prevent its juices from contacting ready-to-eat foods.','Clean hands, knives, boards and surfaces after handling.','For intact boneless portions, cook to at least 63°C / 145°F with a 3-minute rest.']::text[], storage_tips=array['Because the product form is not defined as an intact roast, refrigerate at 4°C or below and use within 1–2 days.','For longer storage, freeze at about -18°C or below and use within about 3–4 months for best quality.']::text[] where name='Ram meat- Boneless' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
